  /* One timeline: the original scenes keep their order (each gets a t no earlier than the one
     before it); everything then sorts by t. */
  let last = 0;
  act.scenes.forEach((sc) => { if (sc.t == null) { sc.t = Math.max(sc.year, last) + 0.0001; } last = Math.max(last, sc.t); });
  act.scenes.sort((a, b) => a.t - b.t);
